export function message(locale, key, values = {}) {
  const template = COPY[locale]?.[key] ?? COPY.en[key];
  if (template === undefined) throw new Error(`Missing CLI message: ${key}`);
  return template.replace(/\{([a-zA-Z]+)\}/g, (match, name) =>
    Object.hasOwn(values, name) ? String(values[name]) : match,
  );
}
